import itertools
def mst_draw(nodes,H,W,free):
    # Kruskal on Manhattan complete graph; draw L path (horiz first or vertical first?), mark cells
    edges=sorted(((abs(a[0]-b[0])+abs(a[1]-b[1]),a,b) for a,b in itertools.combinations(nodes,2)))
    par={n:n for n in nodes}
    def find(x):
        while par[x]!=x: x=par[x]=par[par[x]]
        return x
    drawn=set()
    for c,a,b in edges:
        ra,rb=find(a),find(b)
        if ra==rb: continue
        par[ra]=rb
        (r1,c1),(r2,c2)=a,b
        if r1==r2 or c1==c2:
            pts=[(r,c) for r in range(min(r1,r2),max(r1,r2)+1) for c in ([c1] if r1==r2 else range(min(c1,c2),max(c1,c2)+1))] if r1==r2 else [(r,c1) for r in range(min(r1,r2),max(r1,r2)+1)]
        else:
            # L path: horizontal then vertical
            pts=[(r1,c) for c in range(min(c1,c2),max(c1,c2)+1)]+[(r,c2) for r in range(min(r1,r2),max(r1,r2)+1)]
        for p in pts:
            if p not in nodes: drawn.add(p)
    return drawn
